module tb;
reg [0:0] a,b;
wire [0:0] y;
integer i,j;
dut u(a,b,y);
initial begin
 for(i=0;i<=1;i=i+1) begin
  for(j=0;j<=1;j=j+1) begin
   a=i; b=j; #1;
   if(y !== (a ^ b)) $fatal(1,"Mismatch");
  end
 end
 $display("TEST_PASS"); $finish;
end
endmodule

